                       provides console: NotesConsoleRpc {
  // Activation: register the console's web entry with the WebUI service.
  // The initial state carries the ranker's live strategy and signal count.
  // `add_entry` is an emission on WebUI, so it is called with `emit`.
  emit webui.add_entry(
    asset "./frontend/entry.client.ts",
    "./frontend/dist/.vite/manifest.json",
    ["/notes"],
    { strategy: ranking.strategy(), signals: ranking.signals() },
  )

  provide console {
    fn score(id) = ranking.score(id)

    fn bump(id) {
      let _ = ranking.bump(id)
    }
  }
}

component PrivateNotesHttp requires auth: Auth, store: OwnedNoteStore
                           provides private_api: PrivateNotesApi {
  provide private_api {
    fn get_private_note(bearer, id) {
      return match auth.validate(bearer) {
        Err(e)  => Err(e),
        Ok(who) => store.get(who, id),
      }
    }

    fn list_private_notes(bearer) {
      return match auth.validate(bearer) {
        Err(e)  => Err(e),
        Ok(who) => Ok(store.mine(who)),
      }
    }
  }
}

