component PrivateNotesHttp requires auth: Auth, store: OwnedNoteStore
                           provides private_api: PrivateNotesApi {
  provide private_api {
    fn get_private_note(bearer, id) {
      let result = auth.validate(bearer)
      if (is_ok(result)) {
        return store.get(principal_of(result), id)
      }
      return result
    }

    fn list_private_notes(bearer) {
      let result = auth.validate(bearer)
      if (is_ok(result)) {
        return Ok(store.mine(principal_of(result)))
      }
      return result
    }
  }
}

